CREATE TABLE "users" ("id" SERIAL PRIMARY KEY, "username" VARCHAR(30) NOT NULL, "email" VARCHAR(255) NOT NULL, "password_hash" VARCHAR(255) NOT NULL, "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "users_username_key" ON "users"("username");
CREATE UNIQUE INDEX "users_email_key" ON "users"("email");
CREATE INDEX "ix_users_username" ON "users"("username");
CREATE INDEX "ix_users_email" ON "users"("email");
CREATE TABLE "profiles" ("user_id" INTEGER PRIMARY KEY REFERENCES "users"("id") ON DELETE CASCADE, "display_name" VARCHAR(100) NOT NULL, "avatar_url" VARCHAR(500), "bio" TEXT NOT NULL DEFAULT '', "profile_visibility" VARCHAR(20) NOT NULL DEFAULT 'public', "default_post_audience" VARCHAR(20) NOT NULL DEFAULT 'public', "friend_requests_enabled" BOOLEAN NOT NULL DEFAULT true, "friends_list_visible" BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE "posts" ("id" SERIAL PRIMARY KEY, "user_id" INTEGER NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "text" TEXT NOT NULL DEFAULT '', "audience" VARCHAR(20) NOT NULL DEFAULT 'public', "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "ix_posts_user_id" ON "posts"("user_id");
CREATE INDEX "ix_posts_audience" ON "posts"("audience");
CREATE TABLE "media" ("id" SERIAL PRIMARY KEY, "post_id" INTEGER REFERENCES "posts"("id") ON DELETE CASCADE, "user_id" INTEGER NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "filename" VARCHAR(255) NOT NULL, "media_type" VARCHAR(20) NOT NULL, "mime_type" VARCHAR(100) NOT NULL, "size" INTEGER NOT NULL);
CREATE INDEX "media_post_id_idx" ON "media"("post_id");
CREATE TABLE "comments" ("id" SERIAL PRIMARY KEY, "post_id" INTEGER NOT NULL REFERENCES "posts"("id") ON DELETE CASCADE, "user_id" INTEGER NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "text" TEXT NOT NULL, "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "comments_post_id_idx" ON "comments"("post_id");
CREATE TABLE "likes" ("id" SERIAL PRIMARY KEY, "post_id" INTEGER NOT NULL REFERENCES "posts"("id") ON DELETE CASCADE, "user_id" INTEGER NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, CONSTRAINT "uq_post_like" UNIQUE ("post_id","user_id"));
CREATE INDEX "likes_post_id_idx" ON "likes"("post_id");
CREATE TABLE "friend_requests" ("id" SERIAL PRIMARY KEY, "sender_id" INTEGER NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "receiver_id" INTEGER NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "status" VARCHAR(20) NOT NULL DEFAULT 'pending', "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "uq_friend_request" UNIQUE ("sender_id","receiver_id"));
CREATE TABLE "blocks" ("id" SERIAL PRIMARY KEY, "blocker_id" INTEGER NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "blocked_id" INTEGER NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, CONSTRAINT "uq_block" UNIQUE ("blocker_id","blocked_id"));
CREATE TABLE "notifications" ("id" SERIAL PRIMARY KEY, "user_id" INTEGER NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "actor_id" INTEGER NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "type" VARCHAR(30) NOT NULL, "link" VARCHAR(500) NOT NULL, "message" VARCHAR(500) NOT NULL, "unread" BOOLEAN NOT NULL DEFAULT true, "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "notifications_user_id_idx" ON "notifications"("user_id");
